// debounce.ts
export function debounce(fn: (...args: any[]) => void, waitMs: number) {
    let timer: ReturnType<typeof setTimeout> | null = null;
    return (...args: any[]) => {
        if (timer !== null) {
            clearTimeout(timer);
            timer = null;
            return;
        }
        timer = setTimeout(() => {
            fn(...args);
            timer = null;
        }, waitMs);
    };
}

// Self-test (runs when this file is executed directly)
import { pathToFileURL } from 'node:url';
import assert from 'node:assert';

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
    // Test 1: debounce delays the call and passes the latest arguments
    let calls: any[] = [];
    const debounced1 = debounce((...args: any[]) => {
        calls.push(args);
    }, 50);

    debounced1('a', 1);
    debounced1('b', 2);
    debounced1('c', 3);

    setTimeout(() => {
        assert.strictEqual(calls.length, 1);
        assert.deepEqual(calls[0], ['c', 3]);

        // Test 2: cancels the pending call when a new call arrives
        let callCount = 0;
        const debounced2 = debounce((...args: any[]) => {
            callCount++;
        }, 100);

        debounced2();
        setTimeout(() => {
            debounced2('late');

            setTimeout(() => {
                assert.strictEqual(callCount, 0);

                // Test 3: reschedules with the latest arguments
                let lastArgs: any = null;
                const debounced3 = debounce((...args: any[]) => {
                    lastArgs = args;
                }, 50);

                debounced3('first');
                debounced3('second');

                setTimeout(() => {
                    assert.deepEqual(lastArgs, ['second']);
                    console.log('all tests passed');
                    process.exit(0);
                }, 100);
            }, 100);
        }, 100);
    }, 100);
}

